ORDER_ACTIONS = ("INSPECT_CARAVAN_ORDERS", "DELIVER_CARAVAN_ORDER")
FORMAL_NPCS = ("10011", "10012", "10013", "10014", "10015")


def grant_order_actions(apps, schema_editor):
    Profile = apps.get_model("village", "NpcProfile")
    for profile in Profile.objects.using(schema_editor.connection.alias).filter(npc__agent_id__in=FORMAL_NPCS):
        actions = list(profile.capabilities or [])
        profile.capabilities = actions + [action for action in ORDER_ACTIONS if action not in actions]
        profile.save(update_fields=["capabilities"])


def remove_order_actions(apps, schema_editor):
    Profile = apps.get_model("village", "NpcProfile")
    for profile in Profile.objects.using(schema_editor.connection.alias).filter(npc__agent_id__in=FORMAL_NPCS):
        profile.capabilities = [action for action in (profile.capabilities or []) if action not in ORDER_ACTIONS]
        profile.save(update_fields=["capabilities"])


